                if (!rs.next()) return null;
                return new Object[]{rs.getLong(1), rs.getLong(2), rs.getLong(3), rs.getString(4), rs.getTimestamp(5)};
            }
        }
    }

    static void exec(String sql) throws Exception {
        try (Statement st = raw.createStatement()) {
            st.execute(sql);
        }
    }

